/**
 * Screening and diagnostic tests (September 2026): the part of the map a newly worried person
 * reaches for first. Named products are drug records with a test modality (the kind's public title
 * is "Treatments & tests"); classes of test and screening programmes are technologies; the trials
 * that justify them are trials; the makers are companies; the regulators' framing is in terms.
 *
 * Sources are primary wherever one exists: FDA PMA / De Novo / 510(k) database entries (checked
 * against the accessdata.fda.gov record), USPSTF and NHS pages, trial DOIs. Figures are quoted
 * only when they come from the linked source. Records already in the corpus (Galleri, Shield,
 * Signatera, FoundationOne CDx, Oncotype DX, MammaPrint, Decipher, the PSMA and FES tracers,
 * Cytalux, Lumisight, Lymphoseek) are linked, not duplicated.
 *
 * Wire up with `import { tests } from "./tests";` and `...tests,` in ALL_INPUTS.
 */
import type { CompanyInput, DrugInput, EntityInput, TechnologyInput, TermInput, TrialInput } from "@/lib/schema";
import { TRIAL_OUTCOMES } from "./trial-outcomes";

const asOf = "2026-09-10";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
const PMA = (n: string) => ({ label: `FDA PMA ${n}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpma/pma.cfm?id=${n}` });
const DENOVO = (n: string) => ({ label: `FDA De Novo ${n}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/denovo.cfm?id=${n}` });
const K510 = (n: string) => ({ label: `FDA 510(k) ${n}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID=${n}` });
const DOI = (label: string, doi: string) => ({ label, url: `https://doi.org/${doi}` });
const CT = (nct: string) => ({ label: `ClinicalTrials.gov ${nct}`, url: `https://clinicaltrials.gov/study/${nct}` });

const d = (x: Omit<DrugInput, "kind" | "asOf">): DrugInput => ({ kind: "drug", asOf, tags: ["test", ...(x.tags ?? [])], ...x, });
const tech = (x: Omit<TechnologyInput, "kind" | "asOf">): TechnologyInput => ({ kind: "technology", asOf, ...x });
const co = (x: Omit<CompanyInput, "kind" | "asOf">): CompanyInput => ({ kind: "company", asOf, ...x });
const t = (x: Omit<TrialInput, "kind" | "asOf">): TrialInput => ({ kind: "trial", asOf, ...x, ...TRIAL_OUTCOMES[x.id] });
const term = (x: Omit<TermInput, "kind" | "asOf">): TermInput => ({ kind: "term", asOf, ...x });

